def server_version() -> str:
    """Version of the running server: the installed distribution, else the
    manifest next to this file when run from a source checkout."""
    try:
        from importlib.metadata import version
        return version("apify-data-scrapers")
    except Exception:
        try:
            with open(os.path.join(os.path.dirname(os.path.abspath(__file__)), "manifest.json"), encoding="utf-8") as fh:
                return json.load(fh).get("version", "0.0.0")
        except Exception:
            return "0.0.0"


class ToolFailure(Exception):
    def __init__(self, code, message, retryable=False):
        super().__init__(message)
        self.code, self.message, self.retryable = code, message, retryable


_context = threading.local()


def validate_value(value, schema, path="arguments", code="INVALID_INPUT"):
    """Validate the schema vocabulary used by this catalog without coercing values."""
    def fail(message):
        raise ToolFailure(code, f"{path}: {message}")
    kinds = schema.get("type", [])
    if isinstance(kinds, str):
        kinds = [kinds]
    matches = {
        "null": value is None, "boolean": isinstance(value, bool),
        "integer": isinstance(value, int) and not isinstance(value, bool),
        "number": (isinstance(value, int) and not isinstance(value, bool)) or (isinstance(value, float) and math.isfinite(value)),
        "string": isinstance(value, str), "array": isinstance(value, list), "object": isinstance(value, dict),
    }
    if kinds and not any(matches.get(k, False) for k in kinds):
        fail("expected " + " or ".join(kinds))
    if "enum" in schema and not any(type(value) is type(v) and value == v for v in schema["enum"]):
        fail("value is not an allowed choice")
    if isinstance(value, dict):
        props = schema.get("properties", {})
        for key in schema.get("required", []):
            if key not in value:
                fail(f"missing required field {key}")
        for key, item in value.items():
            if key not in props and schema.get("additionalProperties") is False:
                fail(f"unknown field {key}")
            if key in props:
                validate_value(item, props[key], f"{path}.{key}", code)
    elif isinstance(value, list):
        if len(value) < schema.get("minItems", 0) or len(value) > schema.get("maxItems", float("inf")):
            fail("array length is outside the allowed range")
        for index, item in enumerate(value):
            validate_value(item, schema.get("items", {}), f"{path}[{index}]", code)
    elif isinstance(value, str):
        if len(value) < schema.get("minLength", 0) or len(value) > schema.get("maxLength", float("inf")):
            fail("text length is outside the allowed range")
        if "pattern" in schema and re.search(schema["pattern"], value) is None:
            fail("text does not match the required pattern")
    elif isinstance(value, (int, float)) and not isinstance(value, bool):
        if (isinstance(value, float) and not math.isfinite(value)) or value < schema.get("minimum", -float("inf")) or value > schema.get("maximum", float("inf")):
            fail("number is outside the allowed range")


def get_token() -> str:
    token = os.environ.get("APIFY_TOKEN", "").strip()
    if not token:
        raise ToolFailure("AUTH_REQUIRED", "Set APIFY_TOKEN to your personal Apify token.")
    return token


def _api(method, path, payload=None, timeout=20):
    request = urllib.request.Request(
        APIFY_API_BASE + path,
        data=json.dumps(payload).encode("utf-8") if payload is not None else None,
        headers={"Content-Type": "application/json", "Authorization": "Bearer " + get_token()},
        method=method,
    )
    try:
        with urllib.request.urlopen(request, timeout=timeout) as response:
            result = json.load(response)
            return result.get("data", result) if isinstance(result, dict) else result
    except urllib.error.HTTPError as error:
        # Never return the upstream body: it may contain credentials or input data.
        code = {400: "INVALID_INPUT", 401: "AUTH_REQUIRED", 402: "PAYMENT_REQUIRED", 403: "ACCESS_DENIED", 404: "ACTOR_UNAVAILABLE", 429: "RATE_LIMITED"}.get(error.code, "UPSTREAM_ERROR")
        raise ToolFailure(code, f"Apify returned HTTP {error.code}. Inspect any recorded run before retrying.", method == "GET" and (error.code == 429 or error.code >= 500)) from None
    except (TimeoutError, socket.timeout):
        raise ToolFailure("TIMEOUT", "The Apify request timed out. Inspect the run before retrying.") from None
    except (urllib.error.URLError, OSError):
        raise ToolFailure("NETWORK_ERROR", "Could not reach Apify. Inspect any existing run before retrying.") from None
    except (ValueError, TypeError):
        raise ToolFailure("UPSTREAM_RESPONSE_INVALID", "Apify returned an unexpected response.") from None


def _abort(run_id):
    try:
        result = _api("POST", f"/actor-runs/{run_id}/abort", {}, timeout=10)
        return result.get("status")
    except ToolFailure:
        return "UNCONFIRMED"


def run_actor_sync(actor_id: str, run_input: Dict[str, Any], timeout_secs: int = 120) -> List[Dict[str, Any]]:
    """Start once, retain the run ID, poll within a deadline, then fetch bounded rows."""
    _context.run = None
    try:
        max_charge = float(os.environ.get("APIFY_MAX_CHARGE_USD", "1"))
        if not math.isfinite(max_charge) or not 0 < max_charge <= 100:
            raise ValueError()
    except ValueError:
        raise ToolFailure("CONFIGURATION_ERROR", "APIFY_MAX_CHARGE_USD must be greater than 0 and at most 100.")
    cancel = getattr(_context, "cancel", threading.Event())
    if cancel.is_set():
        raise ToolFailure("CANCELLED", "The request was cancelled before starting.")
    deadline = time.monotonic() + timeout_secs
    query = urllib.parse.urlencode({"timeout": timeout_secs, "maxTotalChargeUsd": max_charge})
    # An ambiguous POST is never retried automatically: it might already have billed a run.
    run = _api("POST", f"/acts/{actor_id.replace('/', '~')}/runs?{query}", run_input, timeout=min(30, timeout_secs))
    if not isinstance(run, dict) or not isinstance(run.get("id"), str):
        raise ToolFailure("START_UNCONFIRMED", "Apify did not return a run ID. Check your Apify runs before retrying.")
    run_id = run["id"]
    _context.run = {"id": run_id, "status": run.get("status"), "url": f"https://console.apify.com/actors/runs/{run_id}", "max_charge_usd": max_charge}
    terminal = {"SUCCEEDED", "FAILED", "ABORTED", "TIMED-OUT"}
    try:
        while run.get("status") not in terminal:
            if cancel.is_set() or time.monotonic() >= deadline:
                status = _abort(run_id)
                _context.run["status"] = status
                raise ToolFailure("CANCELLED" if cancel.is_set() else "TIMEOUT", "Run cancelled or deadline reached. Inspect the recorded run before retrying.")
            cancel.wait(min(1, max(0, deadline - time.monotonic())))
            if cancel.is_set():
                continue
            run = _api("GET", f"/actor-runs/{run_id}", timeout=max(.1, min(15, deadline-time.monotonic())))
            _context.run["status"] = run.get("status")
        if run.get("status") != "SUCCEEDED":
            message = str(run.get("statusMessage") or "").lower()
            code = "TIMEOUT" if run.get("status") == "TIMED-OUT" else "CANCELLED" if run.get("status") == "ABORTED" else "SOURCE_BLOCKED" if any(s in message for s in ("captcha", "source_blocked", "unusual traffic")) else "ACTOR_FAILED"
            raise ToolFailure(code, "The Actor did not complete successfully. Inspect the recorded run.")
        if str(run.get('statusMessage') or '').startswith('PARTIAL:'):
            _context.run['partial'] = True
        limit = min(int(run_input.get("max_items", 100)), 100)
        rows = _api("GET", f"/datasets/{run['defaultDatasetId']}/items?format=json&limit={limit}", timeout=max(.1,min(20,deadline-time.monotonic())))
        if not isinstance(rows, list) or not all(isinstance(row, dict) for row in rows):
            raise ToolFailure("UPSTREAM_RESPONSE_INVALID", "The Actor dataset is not a list of records.")
        return rows
    except ToolFailure:
        if run.get("status") not in terminal and _context.run.get("status") not in terminal:
            _context.run["status"] = _abort(run_id)
        raise


